class ModuleUtilLocatorBase:
    \"\"\"Resolve one import without importing module_utils code on the controller.\"\"\"

    prefix_length = 0
    redirect_first = False

    def __init__(self, fq_name_parts, is_ambiguous=False, child_is_redirected=False):
        self.fq_name_parts = tuple(fq_name_parts)
        self.is_ambiguous = is_ambiguous and len(self.fq_name_parts) > self.prefix_length + 1
        self.child_is_redirected = child_is_redirected
        self.candidate_names = [self.fq_name_parts]
        if self.is_ambiguous:
            self.candidate_names.append(self.fq_name_parts[:-1])
        self.found = False
        self.redirected = False
        self.normalized_name = None
        self.is_package = False
        self.output_path = None
        self.source_code = None
        self.source_path = None
        self.redirect_target = None
        self._resolve()

    def candidate_names_joined(self):
        return ['.'.join(candidate) for candidate in self.candidate_names]

    def _resolve(self):
        for candidate in self.candidate_names:
            methods = (self._redirect, self._local) if self.redirect_first else (self._local, self._redirect)
            for method in methods:
                result = method(candidate)
                if result is None:
                    continue
                source, path, is_package, target = result
                self.found = True
                self.redirected = target is not None
                self.redirect_target = target
                self.normalized_name = candidate + (('__init__',) if is_package else ())
                self.is_package = is_package
                self.output_path = '/'.join(self.normalized_name) + '.py'
                self.source_code = source
                self.source_path = path
                return

    def _redirect(self, candidate):
        return None

    def _local(self, candidate):
        return None

    @staticmethod
    def _shim(name, target):
        return (\"import sys\\nimport {0} as mod\\nsys.modules[{1"'!r}] = mod'"\\n\".format(target, name)).encode('utf-8')


class LegacyModuleUtilLocator(ModuleUtilLocatorBase):
    prefix_length = 2

    def __init__(self, fq_name_parts, is_ambiguous=False, mu_paths=None, child_is_redirected=False):
        self.mu_paths = mu_paths if mu_paths is not None else [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)] + [_MODULE_UTILS_PATH]
        super(LegacyModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous, child_is_redirected)

    def _local(self, candidate):
        relative = candidate[2:]
        if not relative:
            return None
        paths = [os.path.join(p, *relative[:-1]) for p in self.mu_paths]
        try:
            info = ModuleInfo(relative[-1], paths)
        except (ImportError, FileNotFoundError):
            return None
        if not info.py_src and not info.pkg_dir:
            raise AnsibleError('Could not find python source for imported module support code for %s' % '.'.join(candidate))
        return info.get_source(), info.path, info.pkg_dir, None

    def _redirect(self, candidate):
        relative = '.'.join(candidate[2:])
        try:
            entry = _get_collection_metadata('ansible.builtin').get('plugin_routing', {}).get('module_utils', {}).get(relative, {})
        except ValueError:
            return None
        return _routing_result(entry, candidate, 'ansible.builtin')


class CollectionModuleUtilLocator(ModuleUtilLocatorBase):
    prefix_length = 5
    redirect_first = True

    def _metadata(self, candidate):
        collection = '.'.join(candidate[1:3])
        try:
            return _get_collection_metadata(collection), collection
        except ValueError as exc:
            raise AnsibleError(to_native(exc))

    def _redirect(self, candidate):
        if len(candidate) <= 5:
            return None
        metadata, collection = self._metadata(candidate)
        relative = '.'.join(candidate[5:])
        entry = metadata.get('plugin_routing', {}).get('module_utils', {}).get(relative, {})
        return _routing_result(entry, candidate, collection)

    def _local(self, candidate):
        if len(candidate) <= 5:
            return None
        self._metadata(candidate)  # Report missing collections distinctly from missing files.
        package = '.'.join(candidate[:3])
        resource = '/'.join(candidate[3:])
        for path, is_package in ((resource + '/__init__.py', True), (resource + '.py', False)):
            try:
                source = pkgutil.get_data(package, path)
            except (IOError, OSError, ImportError):
                source = None
            if source is not None:
                return source, path, is_package, None
        return None


def _routing_result(entry, candidate, collection):
    if not entry:
        return None
    deprecation = entry.get('deprecation')
    if deprecation:
        display.deprecated(deprecation.get('warning_text') or '%s is deprecated' % '.'.join(candidate),
                           version=deprecation.get('removal_version'), date=deprecation.get('removal_date'),
                           collection_name=collection)
    tombstone = entry.get('tombstone')
    if tombstone:
        raise AnsibleError(display.get_deprecation_message(
            tombstone.get('warning_text') or '%s has been removed' % '.'.join(candidate),
            version=tombstone.get('removal_version'), date=tombstone.get('removal_date'),
            removed=True, collection_name=collection))
    target = entry.get('redirect')
    if not target:
        return None
    if not target.startswith('ansible_collections.') and not target.startswith('ansible.module_utils.'):
        parts = target.split('.')
        if len(parts) >= 3:
            target = 'ansible_collections.%s.%s.plugins.module_utils.%s' % (parts[0], parts[1], '.'.join(parts[2:]))
    return ModuleUtilLocatorBase._shim('.'.join(candidate), target), '/'.join(candidate) + '.py', False, tuple(target.split('.'))


def recursive_finder(name, module_fqn, data, py_module_names, py_module_cache, zf):
    \"\"\"Find and bundle module_utils dependencies using a work queue.\"\"\"
    mu_paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)]
    mu_paths.append(_MODULE_UTILS_PATH)
    pending = deque([(name, module_fqn, data)])
    queued = set()

    def add(name_parts, source, source_path):
        if name_parts in py_module_names or name_parts in queued:
            return
        queued.add(name_parts)
        py_module_cache[name_parts] = (source, source_path)
        pending.append((name_parts[-1], '.'.join(name_parts), source))

    # basic is needed by the AnsiballZ argument wrapper even when the module
    # does not explicitly import it.
    basic = ModuleInfo('basic', mu_paths)
    add(('ansible', 'module_utils', 'basic'), basic.get_source(), basic.path)

    while pending:
        current_name, current_fqn, current_data = pending.popleft()
        try:
            tree = compile(current_data, '<unknown>', 'exec', ast.PyCF_ONLY_AST)
        except (SyntaxError, IndentationError) as exc:
            raise AnsibleError('Unable to import %s due to %s' % (current_name, exc.msg))
        finder = ModuleDepFinder(current_fqn)
        finder.visit(tree)
        for requested in sorted(finder.submodules):
            if requested[:3] == ('ansible', 'module_utils', 'six'):
                requested = ('ansible', 'module_utils', 'six')
            elif requested[:3] == ('ansible', 'module_utils', '_six'):
                requested = ('ansible', 'module_utils', 'six', '_six')
            if requested[:2] == ('ansible', 'module_utils'):
                locator = LegacyModuleUtilLocator(requested, requested in finder.ambiguous_submodules, mu_paths)
            elif requested[:1] == ('ansible_collections',) and len(requested) >= 5 and requested[3:5] == ('plugins', 'module_utils'):
                locator = CollectionModuleUtilLocator(requested, requested in finder.ambiguous_submodules)
            else:
                continue
            if not locator.found:
                raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                                   (current_fqn, ', '.join(locator.candidate_names_joined())))
            resolved = locator.normalized_name
            add(resolved, locator.source_code, locator.source_path)
            if locator.redirected:
                add(tuple(locator.redirect_target), b'', '.'.join(locator.redirect_target)) if False else None
                # Resolve the target as another dependency; its own imports are
                # scanned once its source has been located.
                finder.submodules.add(tuple(locator.redirect_target))
                target = tuple(locator.redirect_target)
                if target[:2] == ('ansible', 'module_utils'):
                    target_locator = LegacyModuleUtilLocator(target, mu_paths=mu_paths)
                else:
                    target_locator = CollectionModuleUtilLocator(target)
                if not target_locator.found:
                    raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                                       (current_fqn, ', '.join(target_locator.candidate_names_joined())))
                add(target_locator.normalized_name, target_locator.source_code, target_locator.source_path)
            # Preserve real package initializer code, including imports.  Namespace
            # levels without an initializer are represented by an empty file.
            bare = resolved[:-1] if resolved[-1] == '__init__' else resolved
            start = 2 if bare[0] == 'ansible' else 1
            for depth in range(start, len(bare)):
                parent = bare[:depth]
                init = parent + ('__init__',)
                if init in py_module_names or init in queued:
                    continue
                source = b''
                source_path = '/'.join(init) + '.py'
                if bare[0] == 'ansible_collections' and depth > 5:
                    parent_locator = CollectionModuleUtilLocator(parent)
                    if parent_locator.found and parent_locator.is_package:
                        source = parent_locator.source_code
                        source_path = parent_locator.source_path
                elif bare[0] == 'ansible' and depth > 2:
                    parent_locator = LegacyModuleUtilLocator(parent, mu_paths=mu_paths)
                    if parent_locator.found and parent_locator.is_package:
                        source = parent_locator.source_code
                        source_path = parent_locator.source_path
                add(init, source, source_path)
        if current_fqn "'!= module_fqn:
            parts = tuple(current_fqn.split('"'.'))
            if parts not in py_module_names:
                source, source_path = py_module_cache.pop(parts)
                zf.writestr('/'.join(parts) + '.py', source)
                py_module_names.add(parts)
                display.vvvvv('Using module_utils file %s' % to_text(source_path))
